import{_ as t,o,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const f=JSON.parse('{"title":"Sequence Flow — View Agency Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-4-view-agency-profile/sequence-flow.md","filePath":"feature/agency-workspace/3-4-4-view-agency-profile/sequence-flow.md"}'),n={name:"feature/agency-workspace/3-4-4-view-agency-profile/sequence-flow.md"};function a(s,e,c,l,d,h){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="sequence-flow-—-view-agency-profile" tabindex="-1">Sequence Flow — View Agency Profile <a class="header-anchor" href="#sequence-flow-—-view-agency-profile" aria-label="Permalink to &quot;Sequence Flow — View Agency Profile&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.4). This file lists each actor → action → system step in enough detail to draw the sequence diagram directly. Business explanation lives in <code>spec.md</code>. &gt; &gt; Updated 2026-09-23, matching the system as built today.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Viewer</strong> — Owner or Member of the Agency; must be signed in, because the profile carries an access check.</li><li><strong>Client</strong> — the BrandHub web application.</li><li><strong>System</strong> — the BrandHub service.</li><li><strong>Database</strong> — PostgreSQL (<code>agencies</code>, <code>agency_members</code>).</li></ul><hr><h2 id="flow-a-—-view-the-agency-profile" tabindex="-1">Flow A — View the Agency profile <a class="header-anchor" href="#flow-a-—-view-the-agency-profile" aria-label="Permalink to &quot;Flow A — View the Agency profile&quot;">​</a></h2><ol><li>Viewer → Client: opens the profile of the Agency.</li><li>Client → System: requests the Agency profile with the signed-in session (<code>GET /api/v1/agencies/{agencyId}</code>). This is the same request the Agency list uses when opening an Agency, as there is no separate profile request.</li><li>System — session check: a missing or invalid session → <code>401 UNAUTHORIZED</code>, refused before the Agency logic runs.</li><li>System — load and authorise: a. Loads the Agency by its identifier — not found → <code>404 AGENCY_NOT_FOUND</code>. b. Confirms whether the caller is the Owner of the Agency. c. Confirms whether the caller holds a member record in the Agency. d. Caller is neither the Owner nor a Member → <code>400 NOT_AGENCY_MEMBER</code>. e. Maps the Agency to its profile.</li><li>System → Client: the profile of the Agency.</li><li>Client: renders the profile — name, logo, description, category, company size, website, phone, location, brand colour, logo icon, tagline, founded year (shown as years in business, counted from the current year), and the Facebook, LinkedIn and Instagram links.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>Error code</th></tr></thead><tbody><tr><td>Session</td><td>Session missing, invalid or expired</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr><tr><td>Load</td><td>Agency does not exist</td><td>404</td><td><code>AGENCY_NOT_FOUND</code></td></tr><tr><td>Authorise</td><td>Caller is neither the Owner nor a Member</td><td>400</td><td><code>NOT_AGENCY_MEMBER</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Correction applied:</strong> an earlier revision described the profile as public, with no sign-in and no access check. That is wrong for the system as built. The request now requires a signed-in session, and the system confirms the caller is the Owner of the Agency or holds a member record in it, refusing anyone else with <code>NOT_AGENCY_MEMBER</code>. The profile is no longer public.</li></ul>',12)])])}const p=t(n,[["render",a]]);export{f as __pageData,p as default};
